// Generated by tooling/unicode-cases/regexp.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Context: legacy i compares UTF-16 units while iu and iv fold the supplementary letter.
const pattern0 = /^\ud83a\udd00$/i;
const pattern1 = /^\ud83a\udd00$/iu;
const pattern2 = /^\ud83a\udd00$/iv;
const samples: [string, boolean, boolean, boolean][] = [
  ["\ud83a\udd00", true, true, true],
  ["\ud83a\udd22", false, true, true],
  ["\ud83a\udd00\ud83a\udd22", false, false, false],
  ["\ud800", false, false, false],
  ["\udc00", false, false, false],
];
for (const sample of samples) {
  assert.sameValue(pattern0.test(sample[0]), sample[1], "adlam-supplementary-fold pattern 0");
  assert.sameValue(pattern1.test(sample[0]), sample[2], "adlam-supplementary-fold pattern 1");
  assert.sameValue(pattern2.test(sample[0]), sample[3], "adlam-supplementary-fold pattern 2");
}
